server {
    listen 80;
    server_name _;

    # ── Proxy /api/* → FastAPI backend ──────────────────────────────────────
    # The frontend calls http://localhost:8000/query etc. in dev mode.
    # In Docker, the backend is reachable at http://backend:8000 (service name).
    # Nginx rewrites /api/query → /query so the backend routes stay unchanged.
    location /api/ {
        proxy_pass         http://backend:8000/;
        proxy_set_header   Host              $host;
        proxy_set_header   X-Real-IP         $remote_addr;
        proxy_set_header   X-Forwarded-For   $proxy_add_x_forwarded_for;
        proxy_read_timeout 120s;   # pipeline calls can take a while
    }

    # ── Serve React SPA ──────────────────────────────────────────────────────
    root /usr/share/nginx/html;
    index index.html;

    location / {
        try_files $uri $uri/ /index.html;
        # ↑ SPA fallback: unknown paths → index.html (React Router handles it)
    }

    # Cache static assets aggressively (hashed filenames by Vite)
    location ~* \.(js|css|png|svg|ico|woff2?)$ {
        expires 1y;
        add_header Cache-Control "public, immutable";
    }
}

